"""Does the corrected joint mechanism actually differ from independent anchors?"""
from core87 import *
N=3;A=np.eye(N);graph={'usable':True,'entities':[{'role':'T','attributes':[]},{'role':'R0','attributes':[]},{'role':'R1','attributes':[]}],'relations':[{'subject':'T','reference':'R0','predicate':'LEFT','known_frame':True},{'subject':'T','reference':'R1','predicate':'LEFT','known_frame':True}]};ev={'means':np.zeros((3,N,13)),'counts':np.zeros((3,N)),'coverage':np.zeros((3,N)),'interval':np.array([[.1,.2],[.4,.5],[.7,.8]]),'reliability':np.ones(N),'labels':np.arange(N)};prior=np.array([.6,.3,.1]);es=np.array([[2.,1.,0.],[0.,1.,3.],[0.,1.,3.]])
p,_,belief=target87(prior,es,graph,ev,A);pi,_,_=target87(prior,es,graph,ev,A,mode='independent');pn,_,_=target87(prior,es,graph,ev,A,mode='no_exclusivity');assert abs(p-pi).sum()>1e-8 and abs(p-pn).sum()>1e-8 and np.isfinite(belief).all() and (belief[1:,-1]>0).all()
dump(H87/'JOINT_COUPLING_AUDIT.json',{'state':'PASS_R87_THREE_ROLE_SHARED_REFERENCE_COMPETITION_DIFFERS_FROM_FIXED_ANCHORS','joint_vs_independent_target_L1':float(abs(p-pi).sum()),'joint_vs_no_exclusivity_target_L1':float(abs(p-pn).sum()),'reference_NULL_retained':True,'dataset_GT_read':False});print('PASS_R87_COUPLING',float(abs(p-pi).sum()))
